package com.yuexin.bmp.agent.task.profit;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DriverManagerDataSource;
import org.springframework.mock.env.MockEnvironment;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;
import com.yuexin.bmp.agent.task.profit.source.ProfitSourceService;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import static org.junit.jupiter.api.Assertions.*;
class RealNoticeDeliveryTest {
 JdbcTemplate db;ObjectMapper json=new ObjectMapper();AtomicInteger sends=new AtomicInteger();DubboProfitNoticeGateway gateway;
 ProfitCardSender sender=new ProfitCardSender(){public void validate(Map<String,Object> r){}public Map<String,Object> send(Map<String,Object> r){sends.incrementAndGet();return queued();}};
 static Map<String,Object> queued(){Map<String,Object> r=new HashMap<>();r.put("state","QUEUED");r.put("noticeAccepted",true);r.put("sendAttempted",true);r.put("assumedSuccess",false);r.put("messageId",null);r.put("readbackConfirmed",false);r.put("deliveryMode","NOTICE_QUEUE");return r;}
 @BeforeEach void setup(){db=new JdbcTemplate(new DriverManagerDataSource("jdbc:h2:mem:"+UUID.randomUUID()+";MODE=MySQL;DB_CLOSE_DELAY=-1","sa",""));db.execute("CREATE TABLE profit_assumed_delivery(slot_hash VARCHAR(64) PRIMARY KEY,idempotency_key VARCHAR(255) UNIQUE,delivery_id VARCHAR(64) UNIQUE,payload LONGTEXT)");db.execute("CREATE TABLE profit_real_delivery(slot_hash VARCHAR(64) PRIMARY KEY,idempotency_key VARCHAR(255) UNIQUE,delivery_id VARCHAR(64) UNIQUE,owner_principal VARCHAR(255),binding_hash VARCHAR(64),state VARCHAR(20),payload LONGTEXT,result LONGTEXT,error_code VARCHAR(64))");gateway=new DubboProfitNoticeGateway(db,json,sender);}
 static Map<String,Object> card(){Map<String,Object> r=new LinkedHashMap<>();r.put("schema","2.0");r.put("header",new HashMap<String,Object>(){{put("title",Collections.singletonMap("content","合成测试卡片"));put("template","red");}});r.put("body",new HashMap<>(Collections.singletonMap("elements",Collections.singletonList(new HashMap<String,Object>(){{put("tag","markdown");put("content","企业：合成企业；利润：20.00 元");}}))));return r;}
 String digest(Object value){try{return ProfitSourceService.hash(new ObjectMapper().enable(SerializationFeature.ORDER_MAP_ENTRIES_BY_KEYS).writeValueAsString(value));}catch(Exception e){throw new RuntimeException(e);}}
 Map<String,Object> request(){Map<String,Object> r=new HashMap<>();r.put("application","enterprise-profit-alert");r.put("dataDay","2026-11-26");r.put("mode","test");r.put("recipientId","synthetic-user");r.put("receiveId","synthetic-feishu-user");r.put("receiveIdType","user_id");r.put("app","BusinessAlarm");r.put("ownerPrincipal","worker");r.put("idempotencyKey","synthetic-key");r.put("rulesetVersion","synthetic-v1");r.put("rulesetSha256",digest("rules"));r.put("inputSha256",digest("input"));r.put("card",card());r.put("cardSha256",digest(r.get("card")));return r;}
 @Test void actualSenderIsCalledOnceAcrossRepeatedRequestsAndRestart(){Map<String,Object> r=request(),first=gateway.invoke("submit",r);assertEquals("QUEUED",first.get("state"));assertEquals(true,first.get("noticeAccepted"));assertEquals(false,first.get("assumedSuccess"));assertNull(first.get("messageId"));assertEquals(false,first.get("readbackConfirmed"));assertEquals(first.get("deliveryId"),new DubboProfitNoticeGateway(db,json,sender).invoke("submit",r).get("deliveryId"));assertEquals(1,sends.get());}
 @Test void changedContentOrKeyIsConflictAndInvalidHashCannotSend(){Map<String,Object> r=request();gateway.invoke("submit",r);r.put("rulesetVersion","changed");assertEquals(409,assertThrows(ProfitApiException.class,()->gateway.invoke("submit",r)).status);Map<String,Object> alias=request();alias.put("idempotencyKey","new-key");assertEquals(409,assertThrows(ProfitApiException.class,()->gateway.invoke("submit",alias)).status);Map<String,Object> bad=request();bad.put("cardSha256",digest("wrong"));assertEquals(400,assertThrows(ProfitApiException.class,()->gateway.invoke("submit",bad)).status);assertEquals(1,sends.get());}
 @Test void timeoutIsDurableUnknownAndNeverResent(){ProfitCardSender bad=new ProfitCardSender(){public void validate(Map<String,Object> r){}public Map<String,Object> send(Map<String,Object> r){sends.incrementAndGet();throw new RuntimeException("response lost after queueing");}};DubboProfitNoticeGateway g=new DubboProfitNoticeGateway(db,json,bad);assertEquals(503,assertThrows(ProfitApiException.class,()->g.invoke("submit",request())).status);assertEquals("UNKNOWN",g.invoke("query","synthetic-key").get("state"));assertEquals("UNKNOWN",g.invoke("submit",request()).get("state"));assertEquals(1,sends.get());}
 @Test void twoInstancesCannotSendTheSameSlot() throws Exception {CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);ExecutorService pool=Executors.newSingleThreadExecutor();ProfitCardSender blocking=new ProfitCardSender(){public void validate(Map<String,Object> r){}public Map<String,Object> send(Map<String,Object> r){sends.incrementAndGet();entered.countDown();try{release.await(5,TimeUnit.SECONDS);}catch(InterruptedException e){throw new RuntimeException(e);}return queued();}};DubboProfitNoticeGateway g=new DubboProfitNoticeGateway(db,json,blocking);try{Future<Map<String,Object>> first=pool.submit(()->g.invoke("submit",request()));assertTrue(entered.await(5,TimeUnit.SECONDS));Map<String,Object> duplicate=new DubboProfitNoticeGateway(db,json,blocking).invoke("submit",request());assertEquals("SUBMITTING",duplicate.get("state"));assertEquals(true,duplicate.get("sendAttempted"));release.countDown();assertEquals("QUEUED",first.get(5,TimeUnit.SECONDS).get("state"));assertEquals(1,sends.get());}finally{release.countDown();pool.shutdownNow();}}
 @Test void readbackDoesNotFabricateConfirmationAndChecksOwner(){Map<String,Object> record=gateway.invoke("submit",request());Map<String,Object> q=new HashMap<>();q.put("deliveryId",record.get("deliveryId"));q.put("ownerPrincipal","other");assertEquals(403,assertThrows(ProfitApiException.class,()->gateway.invoke("readbackOwned",q)).status);q.put("ownerPrincipal","worker");Map<String,Object> result=gateway.invoke("readbackOwned",q);assertEquals(false,result.get("readbackConfirmed"));assertEquals(false,result.get("readbackSupported"));assertEquals("QUEUED",result.get("state"));}
 @Test void historicalPlaceholderIsNotSilentlySent(){db.update("INSERT INTO profit_assumed_delivery VALUES(?,?,?,?)",digest(Arrays.asList("enterprise-profit-alert","2026-11-26","test","synthetic-user")),"synthetic-key","old-placeholder","{}");assertEquals(409,assertThrows(ProfitApiException.class,()->gateway.invoke("submit",request())).status);assertEquals(0,sends.get());}
 @Test void invalidConfigurationOrUnsupportedCardFailsBeforeSend(){LegacyNoticeCardSender real=new LegacyNoticeCardSender(new MockEnvironment());DubboProfitNoticeGateway g=new DubboProfitNoticeGateway(db,json,real);assertEquals(503,assertThrows(ProfitApiException.class,()->g.invoke("submit",request())).status);assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM profit_real_delivery",Integer.class));}
 @Test void legacyNoticeParametersUseUserIdsAndExplicitApp(){LegacyNoticeCardSender real=new LegacyNoticeCardSender(new MockEnvironment().withProperty("profit.notice.url","dubbo://synthetic.invalid:20900"));Map<String,Object> r=request();real.validate(r);Map<String,Object> params=real.parameters(r);assertEquals(Collections.singletonList("synthetic-feishu-user"),params.get("contactIds"));assertEquals("BusinessAlarm",params.get("app"));assertEquals("com.yuexin.platform.notice.service.FeishuNoticeService$CardParams",params.get("class"));Map<?,?> message=(Map<?,?>)params.get("message");assertEquals("合成测试卡片",message.get("title"));assertTrue(message.toString().contains("20.00 元"));r.put("receiveIdType","open_id");assertEquals(400,assertThrows(ProfitApiException.class,()->real.validate(r)).status);}
 @Test void chartConversionPreservesDatesAndExplicitlyLabelsRelativeIndices(){
  Map<String,Object> sample=card();Map<String,Object> chart=new HashMap<>();chart.put("tag","chart");Map<String,Object> spec=new HashMap<>();spec.put("type","line");spec.put("xField","date");spec.put("yField","trendIndex");spec.put("data",Collections.singletonMap("values",Collections.singletonList(new HashMap<String,Object>(){{put("date","11-26");put("trendIndex",73);}})));chart.put("chart_spec",spec);
  ((Map<String,Object>)sample.get("body")).put("elements",Arrays.asList(((List<?>)((Map<?,?>)sample.get("body")).get("elements")).get(0),chart));
  String converted=new NoticeCardAdapter().adapt(sample,20000).toString();assertTrue(converted.contains("20.00 元"));assertTrue(converted.contains("11-26:73"));assertTrue(converted.contains("非利润金额"));
  chart.put("tag","unsupported");assertEquals(400,assertThrows(ProfitApiException.class,()->new NoticeCardAdapter().adapt(sample,20000)).status);
 }
 @Test void realNoticeSubmissionWhenExplicitlyEnabled(){
  org.junit.jupiter.api.Assumptions.assumeTrue("true".equals(System.getProperty("profit.notice.live")));
  String userId=System.getenv("PROFIT_NOTICE_TEST_USER_ID"),url=System.getenv("PROFIT_NOTICE_URL"),file=System.getProperty("profit.notice.live.ledger");
  assertNotNull(userId,"explicit authorized user_id is required");assertNotNull(url);assertNotNull(file,"persistent ledger is mandatory for a real submission");
  JdbcTemplate liveDb=new JdbcTemplate(new DriverManagerDataSource("jdbc:h2:file:"+file+";MODE=MySQL;DB_CLOSE_DELAY=-1","sa",""));
  liveDb.execute("CREATE TABLE IF NOT EXISTS profit_assumed_delivery(slot_hash VARCHAR(64) PRIMARY KEY,idempotency_key VARCHAR(255) UNIQUE,delivery_id VARCHAR(64) UNIQUE,payload LONGTEXT)");
  liveDb.execute("CREATE TABLE IF NOT EXISTS profit_real_delivery(slot_hash VARCHAR(64) PRIMARY KEY,idempotency_key VARCHAR(255) UNIQUE,delivery_id VARCHAR(64) UNIQUE,owner_principal VARCHAR(255),binding_hash VARCHAR(64),state VARCHAR(20),payload LONGTEXT,result LONGTEXT,error_code VARCHAR(64))");
  LegacyNoticeCardSender real=new LegacyNoticeCardSender(new MockEnvironment().withProperty("profit.notice.url",url));
  try{DubboProfitNoticeGateway g=new DubboProfitNoticeGateway(liveDb,json,real);Map<String,Object> r=request();
   r.put("recipientId","notice-self-test");r.put("receiveId",userId);r.put("idempotencyKey","profit-notice-self-test-20261126-"+userId);
   Map<String,Object> sample=card();((Map<String,Object>)sample.get("header")).put("title",Collections.singletonMap("content","利润通知接入测试（合成数据）"));
   ((Map<String,Object>)sample.get("body")).put("elements",Collections.singletonList(new HashMap<String,Object>(){{put("tag","markdown");put("content","这是利润告警接入现有 Notice 的单条测试消息。企业、收入和利润均为合成数据，不代表实际业务告警。合成企业收入 100.00 元，利润 20.00 元。无需处理。此消息仅发给本次授权账号本人。");}}));
   r.put("card",sample);r.put("cardSha256",digest(sample));
   Map<String,Object> result=g.invoke("submit",r);assertEquals("QUEUED",result.get("state"));assertEquals(true,result.get("noticeAccepted"));assertNull(result.get("messageId"));
   System.out.println("NOTICE_LIVE state="+result.get("state")+" deliveryId="+result.get("deliveryId")+" readbackConfirmed=false");
  }finally{real.close();}
 }
}
